    ('GuanWang_Center', 'GongRe_branches_detail_Sheet', 'amount_daily_net_complaints', '2026-04-02'::date, 0.0000),
    ('GuanWang_Center', 'GongRe_branches_detail_Sheet', 'sum_month_total_net_complaints', '2026-04-02'::date, 0.0000),
    ('GuanWang_Center', 'GongRe_branches_detail_Sheet', 'sum_season_total_net_complaints', '2026-04-02'::date, 16.0000),
    ('GuanWang_Center', 'GongRe_branches_detail_Sheet', 'amount_daily_net_complaints', '2026-04-03'::date, 0.0000),
    ('GuanWang_Center', 'GongRe_branches_detail_Sheet', 'sum_month_total_net_complaints', '2026-04-03'::date, 0.0000),
    ('GuanWang_Center', 'GongRe_branches_detail_Sheet', 'sum_season_total_net_complaints', '2026-04-03'::date, 16.0000),
    ('GuanWang_Center', 'GongRe_branches_detail_Sheet', 'amount_daily_net_complaints', '2026-04-04'::date, 0.0000),
    ('GuanWang_Center', 'GongRe_branches_detail_Sheet', 'sum_month_total_net_complaints', '2026-04-04'::date, 0.0000),
    ('GuanWang_Center', 'GongRe_branches_detail_Sheet', 'sum_season_total_net_complaints', '2026-04-04'::date, 16.0000),
    ('GuanWang_Center', 'GongRe_branches_detail_Sheet', 'amount_daily_net_complaints', '2026-04-05'::date, 0.0000),
    ('GuanWang_Center', 'GongRe_branches_detail_Sheet', 'sum_month_total_net_complaints', '2026-04-05'::date, 0.0000),
    ('GuanWang_Center', 'GongRe_branches_detail_Sheet', 'sum_season_total_net_complaints', '2026-04-05'::date, 16.0000)
) AS v(company, sheet_name, item, dt, val)
WHERE d.company = v.company
  AND d.sheet_name = v.sheet_name
  AND d.item = v.item
  AND d.date = v.dt;

-- 【第 3 部分】市平台净投诉量联动同步 (amount_daily_city_net_complaints = amount_daily_net_complaints)
UPDATE daily_basic_data AS d
SET value = c.value,
    operation_time = NOW()
FROM daily_basic_data AS c
WHERE c.sheet_name = d.sheet_name
  AND c.company = d.company
  AND c.date = d.date
  AND c.item = 'amount_daily_net_complaints'
  AND d.item = 'amount_daily_city_net_complaints'
  AND d.sheet_name IN ('GongRe_Sheet', 'GongRe_branches_detail_Sheet')
  AND d.date >= '2025-11-01' AND d.date <= '2026-04-05';

COMMIT;

